import com.itextpdf.kernel.pdf.*;import com.itextpdf.kernel.pdf.canvas.parser.PdfTextExtractor;import java.util.*;import java.util.regex.*;import java.nio.charset.StandardCharsets;
public class TokenAudit{public static void main(String[]a)throws Exception{try(PdfDocument p=new PdfDocument(new PdfReader(a[0]))){String info=p.getDocumentInfo().getMoreInfo("SafeDocsTokenLocationsV1");Set<String> meta=new LinkedHashSet<>();if(info!=null)for(String line:info.lines().skip(1).toList()){String[] f=line.split("\\|",-1);try{meta.add(new String(Base64.getUrlDecoder().decode(f[0]),StandardCharsets.UTF_8));}catch(Exception ignored){}}StringBuilder out=new StringBuilder();for(int n=1;n<=p.getNumberOfPages();n++)out.append(PdfTextExtractor.getTextFromPage(p.getPage(n))).append('\n');String text=out.toString().toUpperCase(Locale.ROOT);Pattern pat=Pattern.compile("\\[[A-Z][A-Z0-9_]*_\\d{3,}]"), chars=Pattern.compile("\\s*([A-Z0-9_\\[\\]])\\s*");Matcher m=pat.matcher(text);Set<String> found=new LinkedHashSet<>();while(m.find())found.add(m.group());System.out.println("documentId="+(info==null?"none":info.lines().findFirst().orElse("")));System.out.println("metadataTokens="+meta.size()+" extractedTokens="+found.size());for(String t:meta)if(!found.contains(t))System.out.println("MISSING "+t);}}}
